import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Track repository updates automatically","description":"Use UTC repository schedules or signed webhooks to detect commits, then verify that fact refresh work was queued and completed.","frontmatter":{"page_id":"guide-automation","description":"Use UTC repository schedules or signed webhooks to detect commits, then verify that fact refresh work was queued and completed."},"headers":[],"relativePath":"en/guide/automation.md","filePath":"en/guide/automation.md","lastUpdated":1786627803000}'),i={name:"en/guide/automation.md"};function r(n,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="track-repository-updates-automatically" tabindex="-1">Track repository updates automatically <a class="header-anchor" href="#track-repository-updates-automatically" aria-label="Permalink to &quot;Track repository updates automatically&quot;">​</a></h1><p>Ershu can check repository commits in two ways: a separate Poller fetches repositories on a UTC cron schedule, or an external system calls a signed webhook. Both paths first determine whether a commit is already analyzed or queued. They create fact-refresh work only when the commit still needs processing.</p><p>Automatic triggers update the repository tree, code index, knowledge graph, and search index. They do not regenerate AI documents. Start a document-capable analysis separately when documents must follow the new commit.</p><h2 id="choose-a-trigger" tabindex="-1">Choose a trigger <a class="header-anchor" href="#choose-a-trigger" aria-label="Permalink to &quot;Choose a trigger&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Best fit</th><th>Additional dependency</th><th>Success signal</th></tr></thead><tbody><tr><td>Scheduled polling</td><td>The repository host cannot notify Ershu, or Ershu should control the check interval</td><td>A continuously running <code>ershu-api-poller</code> and Redis</td><td>A Poller audit record appears and the result is <code>queued</code> or an explained <code>skipped</code></td></tr><tr><td>Signed webhook</td><td>The external system can send a custom HTTP request when a commit changes</td><td>A sender that can calculate Ershu&#39;s HMAC format</td><td>The webhook returns HTTP <code>202</code> with <code>queued</code> or an explained <code>skipped</code></td></tr><tr><td>Manual poll</td><td>You want to validate repository access and change detection immediately</td><td>An authenticated user with project-management permission</td><td>The manual poll returns HTTP <code>202</code> with an interpretable result</td></tr></tbody></table><p>In every case, the Worker claims the actual work from the PostgreSQL queue. When no Worker is running, <code>queued</code> means only that the request reached the queue.</p><h2 id="configure-scheduled-polling" tabindex="-1">Configure scheduled polling <a class="header-anchor" href="#configure-scheduled-polling" aria-label="Permalink to &quot;Configure scheduled polling&quot;">​</a></h2><p>In repository trigger settings, set <code>poll_cron</code> before enabling <code>poll_enabled</code>. The schedule must be a valid five-field cron expression and is always interpreted in UTC. For example, <code>0 * * * *</code> checks at the start of every UTC hour.</p><p>The corresponding management route is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/projects/{project_id}/repositories/{repository_id}/triggers</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Because this request uses an authenticated session and CSRF protection, the web settings page is normally the safer interface. The API rejects an enabled poller without a schedule.</p><p>In the quick deployment, enable the separate Poller service:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-poller.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>By default, the process scans every <code>30</code> seconds and considers at most <code>100</code> due repositories per batch. It holds a renewable Redis lease for <code>120</code> seconds by default, so only the instance that owns the lease performs a scan. See the <a href="./../configuration/environment-reference">environment reference</a> for the supported ranges.</p><p>For one diagnostic cycle, run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;cd /etc/ershu &amp;&amp; exec /opt/ershu/current/.venv/bin/ershu-api-poller --once&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Exit code <code>0</code> only means that the cycle had no unhandled process error. Inspect the repository&#39;s last-poll time, audit records, and new run state to learn whether it found a change.</p><h2 id="configure-a-signed-webhook" tabindex="-1">Configure a signed webhook <a class="header-anchor" href="#configure-a-signed-webhook" aria-label="Permalink to &quot;Configure a signed webhook&quot;">​</a></h2><p>In repository trigger settings, save a <code>webhook_secret</code> of at least <code>16</code> characters before enabling <code>webhook_enabled</code>. Later reads expose only <code>has_webhook_secret</code>; they never return the original secret.</p><p>The webhook endpoint is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/webhooks/repositories/{repository_id}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The JSON body may contain:</p><table tabindex="0"><thead><tr><th>Field</th><th>Constraint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>branch</code></td><td>Optional</td><td>Records the target branch</td></tr><tr><td><code>commit_sha</code></td><td>Optional; exactly 40 or 64 hexadecimal characters</td><td>Selects the exact commit to refresh</td></tr><tr><td><code>event</code></td><td>Optional; at most 64 characters</td><td>Describes the trigger in the result and audit record</td></tr></tbody></table><p>The sender must keep the exact request-body bytes and construct three headers:</p><table tabindex="0"><thead><tr><th>Header</th><th>Content</th></tr></thead><tbody><tr><td><code>X-Ershu-Webhook-Timestamp</code></td><td>Current Unix time; the server permits at most <code>300</code> seconds of skew from the database clock</td></tr><tr><td><code>X-Ershu-Webhook-Nonce</code></td><td>A value unique to this delivery; at most <code>255</code> characters, with no colon or line break</td></tr><tr><td><code>X-Ershu-Webhook-Signature</code></td><td>Lowercase hexadecimal HMAC-SHA256 digest of the message below</td></tr></tbody></table><p>Build the signed message from exact bytes:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UTF-8(timestamp) + NUL + UTF-8(nonce) + NUL + raw_request_body</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Use the repository&#39;s stored <code>webhook_secret</code> as the HMAC key. The signature covers the final transmitted bytes. Reformatting JSON after signing causes authentication to fail. Reusing the same nonce inside the replay-protection window is rejected as well.</p><p>This body shows only the request shape. It has no usable signature and cannot be sent unchanged:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;branch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;commit_sha&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;40-or-64-character-commit&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;push&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="interpret-the-trigger-response" tabindex="-1">Interpret the trigger response <a class="header-anchor" href="#interpret-the-trigger-response" aria-label="Permalink to &quot;Interpret the trigger response&quot;">​</a></h2><p>An authenticated, valid webhook or manual poll returns HTTP <code>202</code>. The response <code>status</code> determines what happened:</p><table tabindex="0"><thead><tr><th><code>status</code></th><th>Common <code>reason</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>queued</code></td><td><code>webhook</code>, <code>poll_detected_change</code>, or the sender&#39;s event</td><td>Fact-refresh work was created or reused for the Worker</td></tr><tr><td><code>skipped</code></td><td><code>commit_already_analyzed</code></td><td>Facts for this branch and commit are already current</td></tr><tr><td><code>skipped</code></td><td><code>commit_already_queued</code></td><td>Work for the same repository, branch, and commit is already queued</td></tr><tr><td><code>skipped</code></td><td><code>local_workspace_dirty</code></td><td>A local workspace has uncommitted changes and is not treated as a reproducible commit</td></tr><tr><td><code>skipped</code></td><td><code>repository_has_no_git_commit</code></td><td>No Git commit can be identified for the workspace</td></tr></tbody></table><p>A <code>queued</code> response includes a <code>run_id</code>. Observe it in the run page or with MCP <code>get_run_status</code>. The automatic refresh is complete only after the run reaches a completed state and the repository tree, code, graph, and search states have updated.</p><h2 id="complete-a-full-check-before-relying-on-it" tabindex="-1">Complete a full check before relying on it <a class="header-anchor" href="#complete-a-full-check-before-relying-on-it" aria-label="Permalink to &quot;Complete a full check before relying on it&quot;">​</a></h2><p>Complete one real end-to-end check before relying on the trigger:</p><ol><li>Save the trigger settings, read them back, and confirm the enabled flags, cron rule, and <code>has_webhook_secret</code>.</li><li>Manually poll a known commit or send one correctly signed test webhook.</li><li>Confirm an HTTP result of <code>queued</code>, or a <code>skipped</code> reason that matches the expected state.</li><li>For <code>queued</code>, confirm that the Worker claims the returned <code>run_id</code>.</li><li>Wait for completion, then inspect the repository commit and freshness of each fact layer.</li><li>Send the same commit again and confirm <code>commit_already_analyzed</code> or <code>commit_already_queued</code> instead of endless duplicate runs.</li></ol><p>If a schedule never fires, first confirm that <code>ershu-api-poller</code> is running separately, then inspect Redis, the UTC cron rule, and repository credentials. The API web process does not execute schedules itself.</p>`,38)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
